import { Component, computed, input } from '@angular/core';
import { HrmAvatar, HrmAvatarStatus } from '../data-display/hrm-avatar';

/** hrm-user-cell — ô người dùng trong bảng: avatar (màu theo tên) + tên + dòng phụ (email/chức danh).
 *  2 loại: đầy đủ (avatar+tên+sub, mặc định cho bảng) và MỘT DÒNG (bỏ sub → avatar+tên, cho bảng dòng đơn).
 *  Chấm hiện diện (status) là OPT-IN — bảng thường KHÔNG dùng; chỉ bật cho màn chấm công/trực tuyến.
 *  Text do bên gọi cấp (i18n-sạch). initials tự suy từ name nếu không truyền. */
@Component({
  selector: 'hrm-user-cell',
  imports: [HrmAvatar],
  template: `
    <hrm-avatar
      [src]="src()"
      [text]="displayInitials()"
      [colorSeed]="name()"
      [colorful]="colorful()"
      [status]="status()"
      [size]="avatarSize()"
      [shape]="shape()" />
    <span class="uc-body">
      <span class="uc-name">{{ name() }}</span>
      @if (sub()) { <span class="uc-sub">{{ sub() }}</span> }
    </span>
  `,
  host: { class: 'hrm-user-cell' },
  styles: [`
/* display:flex (block-level) — không tham gia baseline của td, tránh lệch dòng với ô hai dòng (Text Cell). */
:host { display: flex; align-items: center; gap: 10px; min-width: 0; max-width: 100%; }
.uc-body { display: flex; flex-direction: column; min-width: 0; }
.uc-name { font-size: var(--fs-14); color: var(--text-strong); line-height: 1.35;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.uc-sub { font-size: var(--fs-12); color: var(--text-sub); line-height: 1.3;
  white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  `],
})
export class HrmUserCell {
  readonly src = input('');
  readonly name = input('');
  /** Dòng phụ: email / chức danh / phòng ban. */
  readonly sub = input('');
  /** Chữ viết tắt trong avatar; bỏ trống = tự suy từ name. */
  readonly initials = input('');
  readonly status = input<HrmAvatarStatus | null>(null);
  readonly colorful = input(true);
  readonly shape = input<'circle' | 'square'>('circle');
  readonly avatarSize = input<number | 'small' | 'default' | 'large'>('default');

  protected readonly displayInitials = computed(() => {
    if (this.initials()) return this.initials();
    const n = this.name().trim();
    if (!n) return '';
    const parts = n.split(/\s+/);
    const first = parts[0][0] ?? '';
    const last = parts.length > 1 ? parts[parts.length - 1][0] : '';
    return (first + last).toUpperCase();
  });
}
